"""Collect the author's first video-list response generated by the Bilibili page."""
import html
import re
from urllib.parse import parse_qs, urlparse
from ...errors import CollectionError, RiskControlError, UserNotFoundError
from .common import (exclusion_reason, prefer_bio, normalize_data,
                     excluded_post_counts, recover_saved_failure, folder_id)

LOGIN_COOKIES = ('SESSDATA',)
CDN_DOMAINS = ('hdslb.com', 'biliimg.com', 'bilivideo.com')


def collection_url(url, user_id):
    # The site's compatible /video entry initializes the Videos tab reliably;
    # the dataset keeps the exact URL supplied by the user.
    return f'https://space.bilibili.com/{user_id}/video'


def parse_payload(payload, user_id, *, feed=False):
    data = payload.get('data') or {}
    if not feed:
        return ({'name': data.get('name', ''), 'bio': data.get('sign', '')}
                if str(data.get('mid')) == user_id else {}), []
    videos = []
    for item in data.get('list', {}).get('vlist', []) or []:
        if str(item.get('mid', user_id)) != user_id or not re.fullmatch(r'BV[A-Za-z0-9]{10}', item.get('bvid', '')):
            continue
        identity = item['bvid']
        cover = item.get('pic', '')
        if cover.startswith('//'):
            cover = 'https:' + cover
        elif cover.startswith('http://'):
            cover = 'https://' + cover[7:]
        videos.append({'id': identity, 'title': html.unescape(re.sub(r'<[^>]+>', '', item.get('title', ''))),
                       'url': f'https://www.bilibili.com/video/{identity}', 'cover_url': cover,
                       'content_type': 'video', 'source': 'profile_response',
                       'type_evidence': ['author_video_list', 'bvid']})
    return {}, videos


async def parse_response(response, user_id):
    parsed = urlparse(response.url)
    if parsed.hostname != 'api.bilibili.com':
        return None
    query = parse_qs(parsed.query)
    if query.get('mid', [''])[0] != user_id:
        return None
    feed = parsed.path in ('/x/space/wbi/arc/search', '/x/space/arc/search')
    profile = parsed.path in ('/x/space/wbi/acc/info', '/x/space/acc/info')
    if not (feed or profile):
        return None
    if getattr(response.request, 'method', 'GET') != 'GET':
        return None
    if feed and (query.get('pn', ['1'])[0] != '1' or query.get('keyword', [''])[0] or query.get('tid', ['0'])[0] != '0'):
        return None
    if getattr(response, 'status', 200) in (412, 429):
        raise RiskControlError(f'哔哩哔哩访问受限（HTTP {response.status}）；已停止采集，请在浏览器完成验证后重试。')
    payload = await response.json()
    code = payload.get('code')
    if code in (-352, -412, -799):
        raise RiskControlError(f'哔哩哔哩拒绝访问（{code}）：{payload.get("message", "访问验证或请求限流")}；已停止采集。')
    if code in (-404, 62002):
        raise UserNotFoundError('哔哩哔哩用户不存在或已注销。')
    if code != 0:
        if feed:
            raise CollectionError(f'哔哩哔哩作品列表错误（{code}）：{payload.get("message", "未知错误")}。')
        return None
    info, videos = parse_payload(payload, user_id, feed=feed)
    return info, videos, feed


DOM_SCRIPT = r'''() => {
 const value = selector => {const el=document.querySelector(selector);return el?.getAttribute('title') || el?.textContent?.trim() || ''};
 const name=value('.upinfo-detail .nickname') || value('#h-name');
 const bio=value('.header-sign .pure-text') || value('#h-sign');
 const videos=[],known=new Set();
 // Restrict fallback extraction to the author's upload area, excluding site navigation.
 const root=document.querySelector('main.route_uploadVideo, #submit-video');
 for(const a of root?.querySelectorAll('a[href*="/video/BV"]') || []){
   const id=a.href.match(/\/video\/(BV[A-Za-z0-9]{10})/)?.[1];if(!id)continue;
   const card=a.closest('.bili-video-card,.upload-video-card,.small-item') || a.parentElement;
   const title=a.getAttribute('title') || card?.querySelector('[title]')?.getAttribute('title') || a.textContent.trim();
   const img=card?.querySelector('img');const cover=img?.currentSrc || img?.getAttribute('data-src') || img?.src || '';
   if(known.has(id) || !title)continue;known.add(id);
   videos.push({id,title,url:'https://www.bilibili.com/video/'+id,cover_url:cover.startsWith('//')?'https:'+cover:cover,
     content_type:'video',source:'profile_dom',type_evidence:['author_upload_area','actual_video_link']});
 }
 const countText=value('.side-nav__item.active .side-nav__item__sub-text');
 const count=/^\d+$/.test(countText)?Number(countText):null;
 const empty=!!document.querySelector('.empty-content__tips') && /还没投过视频|暂无视频/.test(root?.textContent || '');
 return {name,bio,videos,video_count:count,no_posts:count===0&&empty};
}'''


async def read_dom(page):
    return await page.evaluate(DOM_SCRIPT)


def check_page(dom, body_text):
    if not dom.get('name') and re.search(r'用户不存在|账号已注销|账号不存在', body_text):
        raise UserNotFoundError('哔哩哔哩用户不存在或已注销。')
    if not dom.get('videos') and re.search(r'访问过于频繁|请求过于频繁|安全验证|验证码', body_text):
        raise RiskControlError('哔哩哔哩要求验证或限制访问；已停止采集，请正常完成验证后重试。')


def finalize(channel, dom, output, first_page_posts, first_feed_received, require_video_types):
    if dom.get('video_count', 0) and not channel['videos']:
        raise CollectionError(f'哔哩哔哩显示有 {dom["video_count"]} 个视频，但首屏作品列表未加载成功；没有将其当作未投稿账户保存，请稍后重试。')
    return channel


async def begin_login(page):
    button = page.get_by_text('登录', exact=True)
    if await button.count():
        await button.first.click()
